import React, { useState } from 'react';
import { Cat, Dog, Bone, Fish, PawPrint, Check, Star } from 'lucide-react';

const Worksheet = () => {
  const [counts, setCounts] = useState({ cats: '', dogs: '' });
  const [selectedFood, setSelectedFood] = useState({ dog: null, cat: null });
  const [showFeedback, setShowFeedback] = useState(false);

  // נתוני ספירה
  const itemsToCount = [
    { type: 'cat', id: 1 },
    { type: 'dog', id: 2 },
    { type: 'cat', id: 3 },
    { type: 'dog', id: 4 },
    { type: 'cat', id: 5 },
    { type: 'cat', id: 6 },
    { type: 'dog', id: 7 },
  ];

  const checkAnswers = () => {
    setShowFeedback(true);
  };

  const isCountCorrect = (type) => {
    if (type === 'cat') return counts.cats === '4';
    if (type === 'dog') return counts.dogs === '3';
    return false;
  };

  return (
    <div dir="rtl" className="min-h-screen bg-orange-50 p-4 md:p-8 font-sans">
      <div className="max-w-3xl mx-auto bg-white rounded-3xl shadow-xl overflow-hidden border-4 border-orange-200 print:border-2 print:shadow-none">

        {/* כותרת */}
        <header className="bg-orange-100 p-6 text-center border-b-4 border-orange-200 print:border-b-2">
          <div className="flex justify-center items-center gap-4 mb-2">
            <PawPrint className="text-orange-500 w-8 h-8 rotate-12" />
            <h1 className="text-4xl font-bold text-orange-800 tracking-wide">דַּף עֲבוֹדָה: חֲתוּלִים וּכְלָבִים</h1>
            <PawPrint className="text-orange-500 w-8 h-8 -rotate-12" />
          </div>
          <div className="mt-4 flex gap-2 justify-center items-center print:justify-start">
            <span className="text-xl font-bold text-gray-600">שֵׁם הַתַּלְמִיד/ה:</span>
            <div className="border-b-2 border-gray-400 w-48 h-8"></div>
          </div>
        </header>

        <div className="p-6 space-y-8">

          {/* משימה 1: ספירה */}
          <section className="bg-blue-50 rounded-2xl p-6 border-2 border-blue-100">
            <h2 className="text-2xl font-bold text-blue-800 mb-4 flex items-center gap-2">
              <span className="bg-blue-200 w-8 h-8 rounded-full flex items-center justify-center text-blue-800">1</span>
              כַּמָּה יֵשׁ? סִפְרוּ וְכִתְבוּ אֶת הַמִּסְפָּר.
            </h2>

            <div className="flex flex-wrap justify-center gap-6 mb-6 p-4 bg-white rounded-xl border border-blue-100 min-h-32 items-center">
              {itemsToCount.map((item) => (
                <div key={item.id} className="transform hover:scale-110 transition-transform duration-200">
                  {item.type === 'cat' ? (
                    <Cat className="w-12 h-12 text-pink-500 fill-pink-100" strokeWidth={2} />
                  ) : (
                    <Dog className="w-12 h-12 text-brown-600 fill-orange-100" color="#8B4513" strokeWidth={2} />
                  )}
                </div>
              ))}
            </div>

            <div className="flex justify-around items-center">
              <div className="text-center">
                <div className="flex items-center gap-2 mb-2">
                  <Cat className="w-8 h-8 text-pink-500" />
                  <span className="text-xl font-bold text-gray-700">כַּמָּה חֲתוּלִים?</span>
                </div>
                <input 
                  type="text" 
                  maxLength={1}
                  value={counts.cats}
                  onChange={(e) => setCounts({...counts, cats: e.target.value})}
                  className={`w-16 h-16 text-3xl text-center border-2 rounded-xl focus:outline-none focus:border-pink-400 ${
                    showFeedback && isCountCorrect('cat') ? 'border-green-500 bg-green-50' : 'border-gray-300'
                  }`}
                />
              </div>

              <div className="text-center">
                <div className="flex items-center gap-2 mb-2">
                  <Dog className="w-8 h-8 text-[#8B4513]" />
                  <span className="text-xl font-bold text-gray-700">כַּמָּה כְּלָבִים?</span>
                </div>
                <input 
                  type="text" 
                  maxLength={1}
                  value={counts.dogs}
                  onChange={(e) => setCounts({...counts, dogs: e.target.value})}
                  className={`w-16 h-16 text-3xl text-center border-2 rounded-xl focus:outline-none focus:border-orange-400 ${
                    showFeedback && isCountCorrect('dog') ? 'border-green-500 bg-green-50' : 'border-gray-300'
                  }`}
                />
              </div>
            </div>
          </section>

          {/* משימה 2: מה אוכלים */}
          <section className="bg-green-50 rounded-2xl p-6 border-2 border-green-100">
            <h2 className="text-2xl font-bold text-green-800 mb-4 flex items-center gap-2">
              <span className="bg-green-200 w-8 h-8 rounded-full flex items-center justify-center text-green-800">2</span>
              מָה הֵם אוֹהֲבִים לֶאֱכֹל? (לַחֲצוּ עַל הַתְּשׁוּבָה הַנְּכוֹנָה)
            </h2>

            <div className="grid grid-cols-2 gap-8">
              {/* כלב */}
              <div className="flex flex-col items-center gap-4 bg-white p-4 rounded-xl shadow-sm">
                <Dog className="w-16 h-16 text-[#8B4513]" />
                <div className="flex gap-4">
                  <button 
                    onClick={() => setSelectedFood({...selectedFood, dog: 'bone'})}
                    className={`p-3 rounded-xl border-2 transition-all ${selectedFood.dog === 'bone' ? 'bg-green-100 border-green-500 scale-110' : 'border-gray-200 hover:border-green-300'}`}
                  >
                    <Bone className="w-8 h-8 text-gray-500" />
                  </button>
                  <button 
                    onClick={() => setSelectedFood({...selectedFood, dog: 'fish'})}
                    className={`p-3 rounded-xl border-2 transition-all ${selectedFood.dog === 'fish' ? 'bg-red-100 border-red-500 scale-110' : 'border-gray-200 hover:border-red-300'}`}
                  >
                    <Fish className="w-8 h-8 text-blue-400" />
                  </button>
                </div>
              </div>

              {/* חתול */}
              <div className="flex flex-col items-center gap-4 bg-white p-4 rounded-xl shadow-sm">
                <Cat className="w-16 h-16 text-pink-500" />
                <div className="flex gap-4">
                  <button 
                    onClick={() => setSelectedFood({...selectedFood, cat: 'bone'})}
                    className={`p-3 rounded-xl border-2 transition-all ${selectedFood.cat === 'bone' ? 'bg-red-100 border-red-500 scale-110' : 'border-gray-200 hover:border-red-300'}`}
                  >
                    <Bone className="w-8 h-8 text-gray-500" />
                  </button>
                  <button 
                    onClick={() => setSelectedFood({...selectedFood, cat: 'fish'})}
                    className={`p-3 rounded-xl border-2 transition-all ${selectedFood.cat === 'fish' ? 'bg-green-100 border-green-500 scale-110' : 'border-gray-200 hover:border-green-300'}`}
                  >
                    <Fish className="w-8 h-8 text-blue-400" />
                  </button>
                </div>
              </div>
            </div>
          </section>

          {/* משימה 3: צביעה / קווקו */}
          <section className="bg-purple-50 rounded-2xl p-6 border-2 border-purple-100 print:block">
            <h2 className="text-2xl font-bold text-purple-800 mb-4 flex items-center gap-2">
              <span className="bg-purple-200 w-8 h-8 rounded-full flex items-center justify-center text-purple-800">3</span>
              עִבְרוּ עַל הַקַּוְקַוִים וְצִבְעוּ:
            </h2>

            <div className="flex justify-around items-center">
              <div className="text-center">
                 <div className="text-6xl font-outline-dashed text-gray-300 font-bold mb-2 tracking-widest relative group cursor-default select-none">
                  כֶּלֶב
                  <span className="absolute inset-0 text-black opacity-0 group-hover:opacity-100 transition-opacity">כֶּלֶב</span>
                 </div>
                 <p className="text-sm text-gray-500">הַעֲבִירוּ אֶצְבַּע אוֹ עִפָּרוֹן</p>
              </div>
              <div className="text-center">
                 <div className="text-6xl font-outline-dashed text-gray-300 font-bold mb-2 tracking-widest relative group cursor-default select-none">
                  חָתוּל
                  <span className="absolute inset-0 text-black opacity-0 group-hover:opacity-100 transition-opacity">חָתוּל</span>
                 </div>
                 <p className="text-sm text-gray-500">הַעֲבִירוּ אֶצְבַּע אוֹ עִפָּרוֹן</p>
              </div>
            </div>
          </section>

        </div>

        {/* כפתורי פעולה */}
        <div className="p-6 bg-gray-50 border-t-2 border-gray-100 flex justify-center gap-4 print:hidden">
          <button 
            onClick={checkAnswers}
            className="bg-green-500 hover:bg-green-600 text-white font-bold py-3 px-8 rounded-full shadow-lg transform transition hover:scale-105 flex items-center gap-2"
          >
            <Check size={24} />
            בְּדִיקָה
          </button>

          <button 
            onClick={() => window.print()}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-3 px-8 rounded-full shadow-lg transform transition hover:scale-105"
          >
            הַדְפָּסָה
          </button>
        </div>

        {/* משוב סופי */}
        {showFeedback && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 animate-fade-in print:hidden" onClick={() => setShowFeedback(false)}>
            <div className="bg-white p-8 rounded-3xl text-center max-w-sm mx-4 transform animate-bounce-in shadow-2xl">
              <Star className="w-16 h-16 text-yellow-400 mx-auto mb-4 fill-yellow-400" />
              <h3 className="text-3xl font-bold text-purple-600 mb-2">כָּל הַכָּבוֹד!</h3>
              <p className="text-xl text-gray-600">אַתֶּם אַלּוּפִים!</p>
              <button className="mt-6 bg-purple-500 text-white py-2 px-6 rounded-full font-bold">סְגִירָה</button>
            </div>
          </div>
        )}

      </div>

      {/* CSS מותאם לקווקו */}
      <style>{`
        .font-outline-dashed {
          -webkit-text-stroke: 2px #cbd5e1;
          -webkit-text-fill-color: transparent;
          stroke-dasharray: 4, 4;
        }
        @media print {
          .print\\:hidden { display: none !important; }
          .print\\:border-2 { border-width: 2px !important; }
          .print\\:shadow-none { box-shadow: none !important; }
          body { background: white; }
        }
      `}</style>
    </div>
  );
};

export default Worksheet;

